import type { PackedLexicon } from "./convert";
import type { Atlas, Grade, Topic, WordRef } from "./types";
import { bandOfGrade } from "../lib/grade";

/** Expand the packed src/data/lexicon-v2.json (generated by `npm run data`). */
export function buildAtlas(raw: PackedLexicon): Atlas {
  const topics: Topic[] = raw.topics.map((t) => ({ ...t }));
  const words: WordRef[] = raw.words.map(([id, word, zh, pos, grade, topic, emoji, glyph, wa, waFlags], order) => ({
    id,
    word,
    zh,
    pos,
    emoji,
    glyph,
    wa: wa ?? "",
    waFlags: waFlags ?? 0,
    grade: grade as Grade,
    band: bandOfGrade(grade as Grade),
    topic,
    topicId: topics[topic].id,
    order,
  }));
  return {
    id: raw.id,
    name: "小词芽词库",
    count: words.length,
    topics,
    words,
    byId: new Map(words.map((w) => [w.id, w])),
    aliases: { ...raw.aliases },
  };
}

/** Words of one topic, optionally limited to a grade (0 = every grade). */
export function topicWords(atlas: Atlas, topicId: string, grade = 0): WordRef[] {
  return atlas.words.filter((w) => w.topicId === topicId && (!grade || w.grade === grade));
}
